#!/usr/bin/env python3
"""Final verification pass for all definition-of-done items."""
import json
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

def run_cmd(host, dtype, user, pwd, cmds):
    results = {}
    conn = ConnectHandler(host=host, device_type=dtype, username=user, password=pwd)
    for cmd in cmds:
        try:
            results[cmd] = conn.send_command(cmd, read_timeout=30)
        except Exception as e:
            results[cmd] = f"ERROR: {e}"
    conn.disconnect()
    return results

def vyos(host):
    return {"host": host, "dtype": "vyos", "user": "vyos", "pwd": "test"}

def mikrotik(host):
    return {"host": host, "dtype": "mikrotik_routeros", "user": "admin", "pwd": "test"}

def linux(host):
    return {"host": host, "dtype": "linux", "user": "root", "pwd": "alpine"}

def main():
    results = {}

    print("=== Phase 1: Collect router state ===")
    tasks = {
        "HQ-Edge": (vyos("192.168.122.11"), [
            "show ip ospf neighbor",
            "show ip bgp summary",
            "show ip bgp",
            "show ip route",
            "show ip bgp neighbors 203.0.113.1 advertised-routes",
            "show ip bgp neighbors 203.0.113.5 advertised-routes",
        ]),
        "Hub-A": (vyos("192.168.122.12"), [
            "show ip ospf neighbor",
            "show ip route",
        ]),
        "Hub-B": (vyos("192.168.122.13"), [
            "show ip ospf neighbor",
            "show ip route",
        ]),
        "Branch-1": (mikrotik("192.168.122.21"), [
            "/routing ospf neighbor print detail",
            "/ip route print terse",
        ]),
        "Branch-2": (mikrotik("192.168.122.22"), [
            "/routing ospf neighbor print detail",
            "/ip route print terse",
        ]),
        "Branch-3": (mikrotik("192.168.122.23"), [
            "/routing ospf neighbor print detail",
            "/ip route print terse",
        ]),
        "Branch-4": (mikrotik("192.168.122.24"), [
            "/routing ospf neighbor print detail",
            "/ip route print terse",
        ]),
    }

    with ThreadPoolExecutor(max_workers=7) as pool:
        futures = {}
        for name, (params, cmds) in tasks.items():
            futures[pool.submit(run_cmd, params["host"], params["dtype"], params["user"], params["pwd"], cmds)] = name
        for f in as_completed(futures):
            name = futures[f]
            results[name] = f.result()

    for name in ["HQ-Edge", "Hub-A", "Hub-B", "Branch-1", "Branch-2", "Branch-3", "Branch-4"]:
        print(f"\n--- {name} ---")
        for cmd, output in results[name].items():
            print(f"  [{cmd}]")
            print(output)

    # Phase 2: Host reachability
    print("\n\n=== Phase 2: Host reachability ===")

    non_guest = {
        "B1-PC1": ("192.168.122.31", "10.1.1.10"),
        "B1-PC2": ("192.168.122.32", "10.1.1.11"),
        "B2-PC1": ("192.168.122.33", "10.1.2.10"),
        "B2-PC2": ("192.168.122.34", "10.1.2.11"),
        "B3-PC1": ("192.168.122.35", "10.1.3.10"),
        "B3-PC2": ("192.168.122.36", "10.1.3.11"),
        "B4-PC1": ("192.168.122.37", "10.2.1.10"),
        "B4-PC2": ("192.168.122.38", "10.2.1.11"),
    }
    guest = {
        "B4-PC3": ("192.168.122.39", "10.2.2.10"),
        "B4-PC4": ("192.168.122.40", "10.2.2.11"),
    }
    all_hosts = {**non_guest, **guest}

    def ping_from_host(mgmt_ip, src_name, targets):
        """Ping a list of target IPs from host at mgmt_ip. Returns dict of target -> pass/fail."""
        conn = ConnectHandler(host=mgmt_ip, device_type="linux", username="root", password="alpine")
        pings = {}
        for tname, tip in targets:
            output = conn.send_command(f"ping -c 2 -W 2 {tip}", read_timeout=15)
            success = "bytes from" in output or " 0% packet loss" in output
            pings[f"{src_name} -> {tname} ({tip})"] = "PASS" if success else "FAIL"
        conn.disconnect()
        return pings

    # Build ping tasks
    ping_results = {}
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = {}
        for src_name, (src_mgmt, src_lab) in all_hosts.items():
            targets = []
            # Ping all other hosts
            for dst_name, (dst_mgmt, dst_lab) in all_hosts.items():
                if dst_name != src_name:
                    targets.append((dst_name, dst_lab))
            # Ping internet
            targets.append(("8.8.8.8", "8.8.8.8"))
            targets.append(("1.1.1.1", "1.1.1.1"))
            futures[pool.submit(ping_from_host, src_mgmt, src_name, targets)] = src_name

        for f in as_completed(futures):
            name = futures[f]
            try:
                ping_results.update(f.result())
            except Exception as e:
                print(f"  ERROR collecting pings from {name}: {e}")

    # Categorize results
    non_guest_names = set(non_guest.keys())
    guest_names = set(guest.keys())

    ng_to_ng_pass = 0
    ng_to_ng_fail = 0
    ng_to_ng_failures = []
    guest_to_guest_pass = 0
    guest_to_guest_fail = 0
    guest_to_guest_failures = []
    cross_pass = 0
    cross_fail = 0
    cross_passes = []
    internet_pass = 0
    internet_fail = 0
    internet_failures = []

    for pair, result in sorted(ping_results.items()):
        src = pair.split(" -> ")[0]
        dst_part = pair.split(" -> ")[1]
        dst = dst_part.split(" (")[0]

        if dst in ("8.8.8.8", "1.1.1.1"):
            if result == "PASS":
                internet_pass += 1
            else:
                internet_fail += 1
                internet_failures.append(pair)
        elif src in non_guest_names and dst in non_guest_names:
            if result == "PASS":
                ng_to_ng_pass += 1
            else:
                ng_to_ng_fail += 1
                ng_to_ng_failures.append(pair)
        elif src in guest_names and dst in guest_names:
            if result == "PASS":
                guest_to_guest_pass += 1
